    course_description = '<p>This qualification reflects the role of individuals working as developing and emerging leaders and managers in a range of enterprise and industry contexts.</p> <p>As well as assuming responsibility for their own performance, individuals at this level are likely to provide leadership, guidance and support to others. They may also have some responsibility for organising and monitoring the output of teams.</p> <p>They apply solutions to a defined range of predictable and unpredictable problems, and analyse and evaluate information from a variety of sources.</p> <p>52 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$8,000 *</strong></p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Resources Fee: <strong>$200</strong></p>',
