UPDATE courses SET
    course_description = '<p>This qualification reflects the role of an individual This qualification reflects the role of individuals in a variety of Business Services job roles. These individuals may have frontline management accountabilities. </p> <p>Individuals in these roles carry out moderately complex tasks in a specialist field of expertise that requires business operations skills. They may possess substantial experience in a range of settings but seek to further develop their skills across a wide range of business functions. </p> <p>52 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$8,000 *</strong></p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Resources Fee: <strong>$200</strong></p>',
