    offshore_tuition_fee = '8000',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">The course will be available for those students who have completed Australian Year 12 or equivalent level of schooling or a Certificate IV or higher qualification with an Australian institution or have two years equivalent full-time relevant workplace experience in a similar role. International Students are required to have an English ability at the IELTS 6.0 or equivalent. </p>',
    created_at = NOW(),
