UPDATE courses SET
    course_description = '<p>This qualification reflects the role of individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts. Individuals at this level display initiative and judgement in planning, organising, implementing and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements. They may plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse and synthesise information from a variety of sources.</p> <p> The course is targetted to domestic and international students who require skills in management as well as those with substantial experience in business/management industry gained through employment but who lack a formal management qualification. </p> <p>52 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$8,000 *</strong></p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Resources Fee: <strong>$200</strong></p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '8000',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">The course will be available for those students who are 18 years or older and have completed Year 12. International Students are also required to have an English ability at the IELTS 6.0 or equivalent.</p> <p class="aos-init" data-aos="fade-up">There are no pre-requisites for this qualification.</p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://vet.apexaustralia.edu.au/courses/bsb50420-diploma-of-leadership-and-management'
WHERE cricos_course_code = '104223J';


UPDATE courses SET
    course_description = '<p>This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts. Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters. They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p> <p> The course is targetted to domestic and international students who require skills in management as well as those with substantial experience in business/management industry gained through employment but who lack a formal management qualification. </p> <p>78 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$10,000 *</strong></p> <p>Enrolment Fee: <strong> $300 **</strong></p> <p>Resources Fee: <strong>$400</strong></p>',
    total_course_duration = '78 Weeks',
    offshore_tuition_fee = '10000',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">The course will be available for those students who:</p> <p> International Students are also required to have an English ability at the IELTS 6.0 or equivalent. </p>',
    created_at = NOW(),
