    apply_form = 'https://vet.apexaustralia.edu.au/courses/bsb60420-advanced-diploma-of-leadership-and-management'
WHERE cricos_course_code = '105605J';


UPDATE courses SET
    course_description = '<p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others. This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director. </p> <p>The course is targetted to domestic and international students who wish to undertake this course in order to access employment in a senior administrative role or further study opportunities. Students will possess significant theoretical business skills and knowledge that they wish to consolidate. Students may have gained these skills and knowledge by completing a relevant advanced diploma level course e.g. the BSB60215 Advanced Diploma of Business or through relevant work experience.</p> <p>78 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$13,500 *</strong></p> <p>Enrolment Fee: <strong>$500 **</strong></p> <p>Resources Fee: <strong>$1000</strong></p>',
    total_course_duration = '78 Weeks',
    offshore_tuition_fee = '13500',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">There are no formal entry requirements specified in the BSB Training Package. The course will be available for those students who are 18 years or older and completed Year 12 or equivalent.</p> <p class="aos-init" data-aos="fade-up">International Students are required to have an English ability at the IELTS 6.0 or equivalent.</p> <p class="aos-init" data-aos="fade-up">Students are required to have completed the equivalent of a Diploma or higher in a relevant field or have 2 years’ work experience in a relevant field. </p> <p class="aos-init" data-aos="fade-up">All students are required to undertake a pre-training review which aims to identify their training needs through questions on previous education or training, relevance of the courses to learner, and relevant experience. </p> <p class="aos-init" data-aos="fade-up">There are no pre-requisites for this qualification. </p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://vet.apexaustralia.edu.au/courses/bsb80120-graduate-diploma-of-management-learning'
WHERE cricos_course_code = '105604K';


UPDATE courses SET
    course_description = '<p>This qualification reflects the roles of community services workers involved in the delivery, management and coordination of person-centred services to individuals, groups, and communities.</p> <p>At this level, workers have specialised skills in community services and work autonomously under broad directions from senior management. Workers are usually providing direct support to individuals or groups of individuals. Workers may also have responsibility for the supervision of other workers and volunteers. They may also undertake case management and program coordination.</p> <p>104 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$20,000 *</strong></p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Resources Fee: <strong>$1,500</strong></p>',
