UPDATE courses SET
    course_description = '<p>This is a trade qualification for carpenters in residential and commercial workplaces. It includes setting out, manufacturing, constructing, assembling, installing and repairing products made using timber and non-timber materials.</p> <p>State and territory jurisdictions may have different licensing, legislative, regulatory or certification requirements. Relevant state and territory regulatory authorities should be consulted to confirm those requirements.</p> <p>Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCWHS1001 Prepare to work safely in the construction industry meets this requirement.</p> <p>The course is targetted to domestic and international students who wish to undertake this course in order to access employment as a carpenter in a commercial, formwork or residential environment. Employees who have previously gained these skills and knowledge through relevant work experience can also enrol in this course.</p> <p>104 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$26,000 *</strong></p> <p>Enrolment Fee: <strong>$500 **</strong></p> <p>Resources Fee: <strong>$3000</strong></p>',
    total_course_duration = '104 Weeks',
    offshore_tuition_fee = '26000',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">The course will be available to those students who are 18 years or older and have completed Year 12. International Students are required to have an English ability at the IELTS 6.0 or equivalent. </p> <p class="aos-init" data-aos="fade-up">Although this qualification has no pre-requisites, students are required to complete the CPCWHS1001 Prepare to work safely in the construction industry unit prior to starting the course or within the first term of studies with APEX. </p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://vet.apexaustralia.edu.au/courses/cpc30220-certificate-iii-in-carpentry'
WHERE cricos_course_code = '110139K';


