UPDATE courses SET
    course_description = '<p>This qualification reflects the trade qualified role of a bricklayer, blocklayer or paver who may have responsibility for undertaking heritage bricklaying, refractory bricklaying, bricklaying, blocklaying and paving work in residential, industrial and commercial contexts, in both existing and new constructions. </p> <p class="smalltext" style="font-size: 10px;">Please note: Completion of the general construction induction training program, specified in the Safe Work Australia model Code of Practice: Construction Work, is required by anyone carrying out construction work. Achievement of CPCWHS1001 Prepare to work safely in the construction industry meets this requirement.</p> <p>104 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$24,000 *</strong></p> <p>Enrolment Fee: <strong>$500 **</strong></p> <p>Resources Fee: <strong>$3000</strong></p>',
