UPDATE courses SET
    course_description = '<p>This qualification reflects the role of builders, site managers and managers of small to medium-sized building businesses who apply knowledge of structural principles, codes, standards and legal requirements to Class 1 and 10, to a maximum of two storeys and Class 2 to 9 Type C constructions, and who plan and supervise safe building and construction work, prepare and administer contracts, and who apply quality principles to building and construction projects. </p> <p> Building relates to construction and Site Management is about managing the factors around construction, such as the deployment of crews with specialised skills (including builders), product compliance, deployment of contract specialised skills, weather and site location. </p> <p> Completion of the general construction induction training program specified by the model Code of Practice for Construction Work is required for any person who is to carry out construction work. Achievement of unit CPCWHS1001 Prepare to work safely in the construction industry meets this requirement. </p> <p> Builder licensing varies across States and Territories and requirements additional to the attainment of this qualification may be required. </p> <p> The course is targetted to domestic and international students who wish to undertake this course in order to access employment as a carpenter, builder, construction supervisor, leading hand of a small to medium sized building business. Employees who have previously gained these skills and knowledge through relevant work experience can also enrol in this course. </p> <p>52 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$12,500 *</strong></p> <p>Enrolment Fee: <strong>$500 **</strong></p> <p>Resources Fee: <strong>$1500</strong></p>',
    total_course_duration = '52 Weeks',
    offshore_tuition_fee = '12500',
    entry_requirements = '<p class="aos-init" data-aos="fade-up">The course will be available to those students who are 18 years or older and have completed Year 12. International Students are required to have an English ability at the IELTS 6.0 or equivalent. </p> <p class="aos-init" data-aos="fade-up">Although this qualification has no pre-requisites, students are required to complete the CPCWHS1001 Prepare to work safely in the construction industry unit prior to starting the course or within the first term of studies with APEX. </p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://vet.apexaustralia.edu.au/courses/cpc40120-certificate-iv-in-building-and-construction'
WHERE cricos_course_code = '110140F';


UPDATE courses SET
    course_description = '<p>The English for Academic Purposes (EAP) course is designed to equip students with the advanced English language skills needed to succeed in academic settings. This course focuses on enhancing students’ ability to understand and produce academic texts, communicate effectively in academic discussions, and apply critical thinking in English. It is ideal for students planning to undertake further studies in vocational or higher education in Australia.</p> <p>Apex’s EAP course offers a contemporary approach to Academic English Language Teaching, utilising effective teaching methods, a quality textbook, and additional resources. Task-based learning (TBL) is central to the course, providing learners with the necessary Academic English (AE) skills for formal communication in English-based tertiary education. The course integrates well-designed assessments and skills-based tasks, ensuring learners achieve their objectives.</p> <p>Key objectives include:</p> <p>Students undergo placement testing upon arrival to ensure they join a class suitable for their proficiency level. Assessment methods include in-class participation, homework tasks, formal and informal tests, staff interviews, research assignments, computer-assisted language learning (CALL), online tasks, and group activities. Continuous feedback and regular written reports from teachers support student progress.</p> <p>12 to 26 weeks (depending on the student’s entry level and learning objectives).</p> <p>Full-Time</p> <p>Blended Learning</p> <p><strong>Onshore Applications:</strong></p> <p>Tuition Fee: <strong>$300/week</strong> (1-13 weeks); <strong>$280/week</strong> (14-26 weeks)</p> <p>Enrolment Fee: <strong>$250 **</strong></p> <p>Materials Fee: <strong>$200</strong> (13 weeks); <strong>$300</strong> (26 weeks)</p> <p><strong>Offshore Applications:</strong></p> <p>Tuition Fee: <strong>$400/week</strong> (1-13 weeks); <strong>$350/week</strong> (14-26 weeks)</p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Materials Fee: <strong>$250</strong> (13 weeks); <strong>$400</strong> (26 weeks)</p>',
    total_course_duration = '26 weeks',
    offshore_tuition_fee = '400',
    entry_requirements = '',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://vet.apexaustralia.edu.au/courses/english-for-academic-purpose'
WHERE cricos_course_code = 'UNKNOWN';


