UPDATE courses SET
    course_description = '<p>This qualification reflects the role of commercial cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems. This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors.</p> <p class="pt-1"> The course is targetted to domestic and international students who require skills in commercial cookery as well as those with substantial experience in cookery gained through employment but who lack a formal qualification. </p> <p>78 Weeks</p> <p>Full-Time</p> <p>Blended Learning</p> <p>Tuition Fee: <strong>$15,000 *</strong></p> <p>Enrolment Fee: <strong>$300 **</strong></p> <p>Resources Fee: <strong>$1,700</strong></p>',
