UPDATE courses SET
    course_description = '<p style="text-align: justify;">The Bachelor of Information Systems (BIS) program is designed to provide students with comprehensive knowledge and applied hand-on skills across a broad range of key areas of information technology and business systems. The course prepares graduates to enter the exciting and ever-evolving fields of information systems and information technology. The BIS features opportunities to study in contemporary and crucial areas of cyber security, artificial intelligence and data analytics. </p> <p style="text-align: justify;">The course covers design thinking, agile systems development methodologies, and various aspects of enterprise systems so that graduates enter the workforce ready to work in modern organisations.</p> <p style="text-align: justify;">The course is characterised by an end of program capstone unit that provides students with the valuable experience of working on a real-world project drawing together the knowledge and skills acquired over the entire BIS course. Importantly, the course has been designed to meet the Australian Computer Society (ACS) requirements for graduate employment in areas of information technology and information systems.</p>',
    total_course_duration = '3 years',
    offshore_tuition_fee = '64200',
    entry_requirements = '<p>Specific Course Admission Criteria for Bachelor of Information Systems: None</p> <p style="text-align: justify;">General Academic Admission Criteria applies. You are required to read the Admission Criteria and ensure you satisfy the requirements before you apply. </p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://apexhe.nsw.edu.au/courses/bachelor-of-information-systems/'
WHERE cricos_course_code = '114079G';


UPDATE courses SET
    course_description = '<p style="text-align: justify;">The Master of Information Systems (MIS) program is designed to meet the Australia Computer Society (ACS) Core Body of Knowledge (CBoK). </p> <p style="text-align: justify;">The course aims to produce Information Systems (IS) graduates who will be eligible to gain employment in a range of different and modern areas of information technology and information systems. </p> <p style="text-align: justify;">The course is built on providing students with foundational knowledge of core and key areas of information technology and systems. Specialisation units in the second year provide opportunities for study in current important IS areas including cyber security, data analytics and artificial intelligence. </p> <p style="text-align: justify;">The course is characterised by an end of program capstone project comprising two connected units. These capstone units provide students with the opportunity to work in a team to solve a complex real-world business information systems problem, drawing from the knowledge and skills acquired over the whole program of study.</p>',
    total_course_duration = '2 years',
    offshore_tuition_fee = '62400',
    entry_requirements = '<p>Specific Course Admission Criteria for Master of Information Systems: None</p> <p style="text-align: justify;">General Academic Admission Criteria applies. You are required to read the Admission Criteria and ensure you satisfy the requirements before you apply. </p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://apexhe.nsw.edu.au/courses/master-of-information-systems/'
WHERE cricos_course_code = '114939A';


UPDATE courses SET
    course_description = '<p style="text-align: justify;">The Bachelor of Information Technology (BIT) program is designed to provide students with comprehensive knowledge and applied hands-on skills across a broad range of key areas of information technology and in a range of different specialisations.</p> <p style="text-align: justify;">The course prepares graduates to enter the exciting and ever-evolving fields of information technology. The BIT features opportunities to study in contemporary and crucial areas of cloud computing, computer networking, cyber security, software development, and the new field of DevOps.</p> <p style="text-align: justify;">The course is characterised by an end of program capstone unit that provides students with the valuable experience of working on a real-world project drawing together the knowledge and skills acquired over the entire BIT course.</p> <p style="text-align: justify;">Importantly, the course has been designed to meet the Australian Computer Society (ACS) requirements for accreditation that ensures the quality and industry-readiness of graduates that employers look for when seeking staff working in Information Technology.</p>',
    total_course_duration = '3 years',
    offshore_tuition_fee = '64200',
    entry_requirements = '<p>Specific Course Admission Criteria for Bachelor of Information Technology: None</p> <p style="text-align: justify;">General Academic Admission Criteria applies. You are required to read the Admission Criteria and ensure you satisfy the requirements before you apply.</p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://apexhe.nsw.edu.au/courses/117549b-bachelor-of-information-technology/'
WHERE cricos_course_code = '117549B';


