UPDATE courses SET
    course_description = '<p style="text-align: justify;">The Master of Information Technology program is designed to meet the Australia Computer Society’s (ACS) requirements for course accreditation, having fulfilled the Core Body of Knowledge (CBoK) as specified by the ACS. The course aims to produce Information Technology (IT) graduates who will be eligible to gain employment in a range of different and modern areas of Information Technology. Being designed to meet the Australian ACS requirements for accreditation ensures the quality and industry-readiness of its graduates.</p> <p style="text-align: justify;">The course is built on providing students with foundational knowledge of core and key areas of information technology and systems. Specialisation units in the second year provide opportunities for study in current important and contemporary IT areas including Cloud and DevOps Engineering, Computer Networks &amp; Systems Engineering, and Software Engineering. The course is characterised by an end of program capstone project comprising two connected units. These capstone units provide students with the opportunity to work in a team to solve a complex real-world information technology problem, drawing from the knowledge and skills acquired over the whole program of study.</p> <p style="text-align: justify;">The GCIT/GDIT/MIT nested set of courses has been designed to include both a Graduate Certificate of Information Technology and Graduate Diploma of Information Technology as both entry and exit points.</p>',
    total_course_duration = '2 years',
    offshore_tuition_fee = '62400',
    entry_requirements = '<p>Specific Course Admission Criteria for Master of Information Technology: None</p> <p style="text-align: justify;">General Academic Admission Criteria applies. You are required to read the Admission Criteria and ensure you satisfy the requirements before you apply.</p>',
    created_at = NOW(),
    updated_at = NOW(),
    apply_form = 'https://apexhe.nsw.edu.au/courses/117550j-master-of-information-technology/'
WHERE cricos_course_code = '117550J';
